package com.campus.trade.dispute.service;
import com.campus.trade.common.context.UserContext; import com.campus.trade.common.exception.*; import com.campus.trade.common.response.PageResult; import com.campus.trade.dispute.dto.*; import com.campus.trade.dispute.entity.Dispute; import com.campus.trade.dispute.mapper.DisputeMapper; import com.campus.trade.dispute.vo.*; import com.campus.trade.order.entity.*; import com.campus.trade.order.mapper.OrderMapper; import com.campus.trade.order.model.OrderStatus; import com.campus.trade.product.mapper.ProductMapper; import com.campus.trade.user.mapper.UserMapper; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
/** 发起纠纷与管理员裁决；所有订单变更均使用 status=5 条件更新，防止重复裁决。 */
@Service public class DisputeService { private final DisputeMapper disputes; private final OrderMapper orders; private final ProductMapper products; private final UserMapper users; private final ObjectMapper json;
 public DisputeService(DisputeMapper d,OrderMapper o,ProductMapper p,UserMapper u,ObjectMapper j){disputes=d;orders=o;products=p;users=u;json=j;}
 @Transactional public DisputeCreatedVO create(CreateDisputeRequest r){Long uid=UserContext.requireCurrentUser().userId(); TradeOrder o=orders.selectById(r.orderId()).orElseThrow(()->new BizException(ErrorCode.NOT_FOUND,"订单不存在")); if(!Objects.equals(uid,o.getBuyerId())&&!Objects.equals(uid,o.getSellerId()))throw new BizException(ErrorCode.FORBIDDEN,"只有交易双方可以发起纠纷"); if(o.getStatus()!=1&&o.getStatus()!=2)throw conflict("当前订单状态不可发起纠纷"); if(disputes.existsByOrderId(o.getId()))throw conflict("该订单已存在纠纷"); Dispute d=new Dispute();d.setOrderId(o.getId());d.setApplicantId(uid);d.setRespondentId(Objects.equals(uid,o.getBuyerId())?o.getSellerId():o.getBuyerId());d.setReasonType(r.reasonType());d.setStatement(r.statement().trim());d.setEvidenceJson(write(r.evidence()));d.setStatus(0);try{disputes.insert(d);}catch(DuplicateKeyException e){throw conflict("该订单已存在纠纷");}if(orders.enterDispute(o.getId(),uid,o.getStatus())==0)throw conflict("订单状态已变化，请刷新后重试");log(o.getId(),o.getStatus(),5,Objects.equals(uid,o.getBuyerId())?0:1,uid,d.getStatement());return new DisputeCreatedVO(d.getId());}
 @Transactional public void handle(Long id,HandleDisputeRequest r){Long admin=UserContext.requireCurrentUser().userId();Dispute d=disputes.selectById(id).orElseThrow(()->new BizException(ErrorCode.NOT_FOUND,"纠纷不存在"));TradeOrder o=orders.selectById(d.getOrderId()).orElseThrow(()->new BizException(ErrorCode.NOT_FOUND,"订单不存在"));String note=trim(r.note()); switch(r.action()){case "NEED_MORE"->{update(d,1,admin,note);return;}case "REJECT"->{update(d,2,admin,note);if(orders.restoreFromDispute(o.getId(),o.getStatusBeforeDispute())==0)throw conflict("订单状态已变化");log(o.getId(),5,o.getStatusBeforeDispute(),3,admin,note);}case "KEEP_COMPLETED"->{update(d,3,admin,note);if(orders.completeFromDispute(o.getId())==0)throw conflict("订单状态已变化");log(o.getId(),5,2,3,admin,note);}case "CANCEL_TRADE"->{update(d,4,admin,note);if(orders.cancelFromDispute(o.getId())==0)throw conflict("订单状态已变化");if(Boolean.TRUE.equals(r.restock()))products.restoreStockForCancelledOrder(o.getProductId(),o.getQuantity());log(o.getId(),5,3,3,admin,note);}default->throw new BizException(ErrorCode.BAD_REQUEST,"未知处理动作");}}
 public PageResult<AdminDisputeVO> list(Integer status,int page,int pageSize){List<AdminDisputeVO> list=disputes.selectPage(status,pageSize,(page-1)*pageSize).stream().map(d->{TradeOrder o=orders.selectById(d.getOrderId()).orElse(null);return new AdminDisputeVO(d.getId(),d.getOrderId(),d.getReasonType(),d.getStatement(),read(d.getEvidenceJson()),d.getStatus(),o==null?"":o.getOrderNo(),o==null?"":products.selectById(o.getProductId()).map(x->x.getTitle()).orElse(""),o==null?"":users.selectById(o.getBuyerId()).map(x->x.getNickname()).orElse(""),o==null?"":users.selectById(o.getSellerId()).map(x->x.getNickname()).orElse(""),o==null?null:o.getStatus(),d.getCreatedAt());}).toList();return new PageResult<>(list,disputes.count(status),page,pageSize);}
 private void update(Dispute d,int status,Long admin,String note){if(disputes.updateHandled(d.getId(),status,admin,note)==0)throw conflict("该纠纷已处理");} private void log(Long oid,int from,int to,int type,Long uid,String reason){TradeOrderLog l=new TradeOrderLog();l.setOrderId(oid);l.setFromStatus(from);l.setToStatus(to);l.setOperatorType(type);l.setOperatorId(uid);l.setReason(reason);orders.insertLog(l);} private String write(List<String> a){try{return json.writeValueAsString(a==null?List.of():a);}catch(Exception e){throw new IllegalStateException(e);}} private List<String> read(String s){try{return s==null?List.of():json.readValue(s,new TypeReference<>(){});}catch(Exception e){return List.of();}} private String trim(String s){return s==null||s.isBlank()?null:s.trim();}private BizException conflict(String s){return new BizException(ErrorCode.CONFLICT,s);} }
